{
  "aggregate_id": "DEF-LVMC-11-02-140::taxicab",
  "classifications": [
    {
      "class": "ru.bicycle",
      "verdict": "supported",
      "reason": "Taxicabs must be motor vehicles, whereas the vehicle definition excludes devices moved by human power, as the bicycle contract describes."
    },
    {
      "class": "ru.bus",
      "verdict": "underdetermined",
      "reason": "The bus contract does not establish the required taxicab licensing, and that licensing does not establish the markings required for coverage by ru.taxicab."
    },
    {
      "class": "ru.child",
      "verdict": "supported",
      "reason": "A child under this contract is a pedestrian, not the motor vehicle required by the admitting words."
    },
    {
      "class": "ru.commercial_motor_vehicle",
      "verdict": "underdetermined",
      "reason": "Commercial mass or commercial licensing does not establish licensing for taxicab service, and the definition does not require admitted vehicles to bear the markings specified by ru.taxicab."
    },
    {
      "class": "ru.electric_bicycle",
      "verdict": "supported",
      "reason": "The motor-vehicle definition expressly excludes electric bicycles, while the taxicab definition requires a motor vehicle."
    },
    {
      "class": "ru.electric_scooter",
      "verdict": "supported",
      "reason": "The motor-vehicle definition expressly excludes electric scooters, while the taxicab definition requires a motor vehicle."
    },
    {
      "class": "ru.emergency_vehicle",
      "verdict": "underdetermined",
      "reason": "Emergency designation does not settle taxicab licensing, and the admitting words do not guarantee that an admitted emergency vehicle carries the markings required by ru.taxicab."
    },
    {
      "class": "ru.fire_apparatus",
      "verdict": "underdetermined",
      "reason": "The fire-fighting vehicle contract does not settle taxicab licensing, and the definition does not require admitted vehicles to have the markings necessary for ru.taxicab coverage."
    },
    {
      "class": "ru.moped",
      "verdict": "underdetermined",
      "reason": "The moped contract does not establish taxicab licensing, and licensing for taxicab service does not establish the markings required by the proposed covering class."
    },
    {
      "class": "ru.motor_vehicle",
      "verdict": "underdetermined",
      "reason": "The motor-vehicle contract does not establish the additional taxicab-licensing requirement, and the definition does not guarantee the markings required for ru.taxicab coverage."
    },
    {
      "class": "ru.motorcycle",
      "verdict": "underdetermined",
      "reason": "The motorcycle contract does not establish taxicab licensing, and the admitting words do not require admitted motorcycles to carry the markings specified by ru.taxicab."
    },
    {
      "class": "ru.official_vehicle",
      "verdict": "underdetermined",
      "reason": "Official or contracted road service does not establish taxicab licensing, and official livery or equipment does not establish the taxicab markings asserted by the coverage claim."
    },
    {
      "class": "ru.pedestrian",
      "verdict": "supported",
      "reason": "The contract describes a person rather than a motor vehicle, and the vehicle definition additionally excludes electric personal assistive mobility devices."
    },
    {
      "class": "ru.pedestrian_with_white_cane_or_guide_animal",
      "verdict": "supported",
      "reason": "The contract describes a pedestrian with specified assistance, not a motor vehicle admitted by the taxicab definition."
    },
    {
      "class": "ru.rail_vehicle",
      "verdict": "supported",
      "reason": "The motor-vehicle definition expressly requires that the vehicle not be operated upon rails, which rules out the on-track equipment described by this contract."
    },
    {
      "class": "ru.school_bus",
      "verdict": "underdetermined",
      "reason": "School-bus designation and markings do not establish taxicab licensing, and the definition does not guarantee that an admitted school bus bears the markings required by ru.taxicab."
    },
    {
      "class": "ru.taxicab",
      "verdict": "underdetermined",
      "reason": "The contract's marked passenger vehicle for hire does not establish proper licensing under State and local law to provide taxicab service, and the words do not exclude that class either."
    },
    {
      "class": "ru.tour_bus_or_limousine",
      "verdict": "underdetermined",
      "reason": "Tour, shuttle or limousine service does not establish taxicab licensing, and its identifying livery does not guarantee the taxicab markings asserted by the coverage claim."
    },
    {
      "class": "ru.trailer_or_combination",
      "verdict": "underdetermined",
      "reason": "The contract includes combinations whose qualification is not settled by the words, and nothing guarantees that every admitted combination satisfies the marked passenger-for-hire contract of ru.taxicab."
    },
    {
      "class": "ru.transit_bus",
      "verdict": "underdetermined",
      "reason": "Public transit service does not establish taxicab licensing, and transit livery or a route display does not guarantee the taxicab markings asserted by the coverage claim."
    },
    {
      "class": "ru.truck",
      "verdict": "underdetermined",
      "reason": "The goods-carrying motor-vehicle contract does not settle taxicab licensing, and the definition does not establish that every admitted truck is a marked passenger vehicle for hire."
    }
  ]
}

